/**
 * Predicts portion for a specific dish using Engine v2 Ridge-Regression parameters
 */
export function predictPortionsV2(
  dishName: string,
  category: string,
  kids: number,
  adults: number
): number {
  if (kids <= 0 && adults <= 0) return 1

  // 1. Dish-level trained coefficients
  const dish = ENGINE_V2_DISH_MODELS[dishName]
  if (dish) {
    const val = dish.w_kids * kids + dish.w_adults * adults + dish.bias
    return Math.max(1, Math.round(val))
  }

  // 2. Normalized category-level fallback
  const normCat = normalizeCategory(category)
  const catModel = ENGINE_V2_CATEGORY_MODELS[normCat] || ENGINE_V2_CATEGORY_MODELS[category]
  if (catModel) {
    const val = catModel.w_kids * kids + catModel.w_adults * adults + catModel.bias
    return Math.max(1, Math.round(val))
  }

  // 3. Global fallback based on overall average consumption (~0.3 kids + 0.25 adults)
  const fallbackVal = 0.3 * kids + 0.25 * adults + 1.0
  return Math.max(1, Math.round(fallbackVal))
}

/**
 * Auto-populates menu items and portions using the trained v2 Engine
 * @param kidsCount Number of kids
 * @param adultsCount Number of adults
 * @param dietary 'all' or 'veg'
 */
export function autoPopulateMenuV2(
  kidsCount: number,
  adultsCount: number,
  dietary: 'all' | 'veg' = 'all'
): EngineV2Prediction {
  const kids = Math.max(0, kidsCount)
  const adults = Math.max(0, adultsCount)
  const totalPax = kids + adults

  if (totalPax <= 0) {
    return {
      bestMatchId: 0,
      bestMatchPax: '0 Pax',
      selectedMenuIndices: [],
      suggestedChefServers: '₹3,000',
      portionsMap: {}
    }
  }

  // Filter candidate quotations according to dietary preference
  let candidates = ENGINE_V2_QUOTATIONS
  if (dietary === 'veg') {
    const vegCandidates = candidates.filter(q => q.nv === 0)
    if (vegCandidates.length >= 20) {
      candidates = vegCandidates
    }
  }

  // Compute distance to each historical candidate in the manifold
  const scored = candidates.map(q => {
    const dk = kids - q.k
    const da = adults - q.a
    const dp = totalPax - (q.k + q.a)
    // Distance metric weighting kids, adults, and party volume
    const dist = Math.sqrt(1.2 * dk * dk + 1.0 * da * da + 0.8 * dp * dp)
    return { dist, q }
  })

  scored.sort((a, b) => a.dist - b.dist)
  const topK = scored.slice(0, 20)
  const bestMatch = topK[0].q

  // Neighborhood kernel weighting to determine category quotas & dish popularity
  const catTotals: Record<string, number> = {}
  const itemWeights: Record<number, number> = {}
  let weightsSum = 0

  for (const { dist, q } of topK) {
    const weight = 1.0 / (1.0 + dist)
    weightsSum += weight

    const catsInQuote: Record<string, number> = {}
    for (const menuIdx of q.i) {
      const item = menuItems[menuIdx]
      if (!item) continue
      if (dietary === 'veg' && item.VegNonVeg === 'Non-Veg') continue

      const cat = normalizeCategory(item.Category)
      catsInQuote[cat] = (catsInQuote[cat] || 0) + 1
      itemWeights[menuIdx] = (itemWeights[menuIdx] || 0) + weight
    }

    for (const cat in catsInQuote) {
      catTotals[cat] = (catTotals[cat] || 0) + catsInQuote[cat] * weight
    }
  }

  // Determine target item counts per category
  const expectedCats: Record<string, number> = {}
  for (const cat in catTotals) {
    const avg = catTotals[cat] / (weightsSum || 1)
    expectedCats[cat] = Math.max(1, Math.round(avg))
  }

  // Ensure minimum balanced party structure
  if (!expectedCats['Table Snacks'] || expectedCats['Table Snacks'] < 4) {
    expectedCats['Table Snacks'] = 4
  }
  if (!expectedCats['Main Course'] || expectedCats['Main Course'] < 2) {
    expectedCats['Main Course'] = 2
  }
  if (!expectedCats['Dessert'] || expectedCats['Dessert'] < 1) {
    expectedCats['Dessert'] = 1
  }

  // Only include Live Stations or Drinks if heavily represented (> 45% of neighborhood)
  if ((catTotals['Live Stations'] || 0) / (weightsSum || 1) < 0.45) {
    delete expectedCats['Live Stations']
  }
  if ((catTotals['Drinks'] || 0) / (weightsSum || 1) < 0.45) {
    delete expectedCats['Drinks']
  }

  // Select dishes in consistent category order
  const categoryOrder = [
    'Table Snacks',
    'Main Course',
    'Noodles',
    'Rice',
    'Dessert',
    'Drinks',
    'Live Stations'
  ]

  const selectedIndices: number[] = []

  for (const cat of categoryOrder) {
    const targetCount = expectedCats[cat] || 0
    if (targetCount <= 0) continue

    const catCandidates: { idx: number; weight: number }[] = []
    for (const idxStr in itemWeights) {
      const idx = Number(idxStr)
      const item = menuItems[idx]
      if (!item) continue
      if (normalizeCategory(item.Category) !== cat) continue
      if (dietary === 'veg' && item.VegNonVeg === 'Non-Veg') continue
      catCandidates.push({ idx, weight: itemWeights[idx] })
    }

    catCandidates.sort((a, b) => b.weight - a.weight)
    const picked = catCandidates.slice(0, targetCount).map(c => c.idx)
    selectedIndices.push(...picked)
  }

  // Calculate portions for all selected items
  const portionsMap: Record<number, number> = {}
  for (const idx of selectedIndices) {
    const item = menuItems[idx]
    if (item) {
      portionsMap[idx] = predictPortionsV2(item.Name, item.Category, kids, adults)
    }
  }

  // Estimate suggested chef/servers fee from neighborhood
  const validChefs = topK.map(t => t.q.ch).filter(c => c > 0)
  validChefs.sort((a, b) => a - b)
  const medianChef = validChefs.length > 0
    ? validChefs[Math.floor(validChefs.length / 2)]
    : (totalPax > 50 ? 5000 : (totalPax >= 30 ? 4000 : 3000))
  const suggestedChefServers = `₹${medianChef.toLocaleString('en-IN')}`

  return {
    bestMatchId: bestMatch.id,
    bestMatchPax: `${bestMatch.k} Kids ${bestMatch.a} Adults`,
    selectedMenuIndices: selectedIndices,
    suggestedChefServers,
    portionsMap
  }
}
